// Records a demo of http://localhost:5173. Generated by make_demo.py web; edit the steps and re-run.
// Run from the repo root: NODE_PATH=frontend/node_modules node docs/demo/walks.web.js (see docs/demo/README.md)
const { chromium } = require("playwright-core");
const path = require("path");

const fs = require("fs");

// Playwright's video is recorded in CSS pixels (390 px wide, blurry), so this script
// uses Chrome's screencast at 2x pixels instead and writes PNG frames plus an
// ffmpeg concat file with the real frame times.
const OUT_DIR = path.join("demo-video", "walks-frames");
const VIEWPORT = { width: 390, height: 844 };
const PAUSE = 800;

(async () => {
  const browser = await chromium.launch({ headless: true, channel: "chrome" });
  const context = await browser.newContext({
    viewport: VIEWPORT,
    deviceScaleFactor: 2,
    colorScheme: "light",
  });

  // English UI and the fake client id from seed_demo_recording.py.
  await context.addInitScript(() => {
    localStorage.setItem("strollway.language", "en");
    localStorage.setItem(
      "strollway.clientId",
      "00000000-0000-4000-8000-000000000001",
    );
  });

  // Headless video has no mouse pointer, so draw one that follows the mouse.
  await context.addInitScript(() => {
    const draw = () => {
      if (document.getElementById("__demo_cursor")) return;
      const c = document.createElement("div");
      c.id = "__demo_cursor";
      c.style.cssText =
        "position:fixed;z-index:2147483647;pointer-events:none;width:18px;height:18px;" +
        "margin:-9px 0 0 -9px;border-radius:50%;background:rgba(255,80,80,.55);border:2px solid #fff;" +
        "left:-40px;top:-40px;transition:transform .1s";
      document.documentElement.appendChild(c);
      addEventListener(
        "mousemove",
        (e) => {
          c.style.left = e.clientX + "px";
          c.style.top = e.clientY + "px";
        },
        true,
      );
      addEventListener(
        "mousedown",
        () => {
          c.style.transform = "scale(.7)";
        },
        true,
      );
      addEventListener(
        "mouseup",
        () => {
          c.style.transform = "";
        },
        true,
      );
    };
    if (document.readyState === "loading")
      document.addEventListener("DOMContentLoaded", draw);
    else draw();
  });
  const page = await context.newPage();
  fs.rmSync(OUT_DIR, { recursive: true, force: true });
  fs.mkdirSync(OUT_DIR, { recursive: true });
  const frames = [];
  const cdp = await context.newCDPSession(page);
  cdp.on("Page.screencastFrame", async ({ data, metadata, sessionId }) => {
    const file = `${String(frames.length).padStart(5, "0")}.png`;
    fs.writeFileSync(path.join(OUT_DIR, file), Buffer.from(data, "base64"));
    frames.push({ file, time: metadata.timestamp });
    await cdp.send("Page.screencastFrameAck", { sessionId }).catch(() => {});
  });
  await cdp.send("Page.startScreencast", {
    format: "png",
    maxWidth: VIEWPORT.width * 2,
    maxHeight: VIEWPORT.height * 2,
  });
  const moveTo = async (sel) => {
    const box = await page.locator(sel).first().boundingBox();
    if (box)
      await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2, {
        steps: 25,
      });
  };
  // Many small wheel steps look like a real swipe; one big step jumps.
  // The mouse stays in the right gutter, so the wheel scrolls the page, not the map.
  const smoothScroll = async (px) => {
    await page.mouse.move(VIEWPORT.width - 4, VIEWPORT.height / 2, {
      steps: 10,
    });
    for (let done = 0; done < px; done += 20) {
      await page.mouse.wheel(0, 20);
      await page.waitForTimeout(16);
    }
  };
  try {
    await page.goto("http://localhost:5173", { waitUntil: "load" });
    await page.waitForTimeout(1000);
    // "goto /walks"
    await page.goto("http://localhost:5173/walks", { waitUntil: "load" });
    await page.waitForTimeout(PAUSE);
    // "wait 2000"
    await page.waitForTimeout(2000);
    // "click text=Oliwa: playground and coffee"
    await moveTo("text=Oliwa: playground and coffee");
    await page.click("text=Oliwa: playground and coffee");
    await page.waitForTimeout(PAUSE);
    // "wait 2500"
    await page.waitForTimeout(2500);
    // "hover text=Stairs avoided"
    await moveTo("text=Stairs avoided");
    await page.hover("text=Stairs avoided");
    await page.waitForTimeout(PAUSE);
    // "scroll 700"
    await smoothScroll(700);
    await page.waitForTimeout(PAUSE);
    // "wait 2500"
    await page.waitForTimeout(2500);
    // "hover text=Status and rating"
    await moveTo("text=Status and rating");
    await page.hover("text=Status and rating");
    await page.waitForTimeout(PAUSE);
    // "scroll 600"
    await smoothScroll(600);
    await page.waitForTimeout(PAUSE);
    // "wait 2500"
    await page.waitForTimeout(2500);
    await page.waitForTimeout(1500);
  } finally {
    await cdp.send("Page.stopScreencast").catch(() => {});
    // Each frame stays on screen until the next one; the last one for 2 s.
    const lines = ["ffconcat version 1.0"];
    frames.forEach((frame, i) => {
      const next = frames[i + 1];
      const duration = next ? next.time - frame.time : 2;
      lines.push(`file ${frame.file}`, `duration ${duration.toFixed(3)}`);
    });
    lines.push(`file ${frames[frames.length - 1].file}`);
    fs.writeFileSync(path.join(OUT_DIR, "frames.txt"), `${lines.join("\n")}\n`);
    await context.close();
    await browser.close();
  }
  console.log(path.join(OUT_DIR, "frames.txt"));
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
